// paths.ts — where the mod keeps a session's state. Pure.
//
// <config>/kodflow/sessions/<session>/ is shared with the shell hooks and the
// status line: tasks.json (the task list), agents.json (on-agent.sh),
// triage-pending (the triage gate) and mod-beat (the proof the mod is loaded).

/**
 * The Claude configuration directory: CLAUDE_CONFIG_DIR, else ~/.claude.
 * Always absolute: `$.fs` resolves a relative path against the session's
 * working directory and never expands `~`, so anything else is refused.
 */
export function configDir(
  claudeConfigDir: string | undefined,
  home: string | undefined,
): string | undefined {
  const pick =
    claudeConfigDir || (home ? `${home.replace(/\/+$/, "")}/.claude` : "");
  if (!pick.startsWith("/")) return undefined;
  return pick.length > 1 ? pick.replace(/\/+$/, "") : pick;
}

/** Keep an identifier usable as a single path component (tasks.py's safe). */
export function safe(value: unknown): string {
  const chars = [...String(value)].map((c) =>
    /^[\p{L}\p{N}_-]$/u.test(c) ? c : "-",
  );
  return chars.slice(0, 128).join("") || "default";
}

export const sessionDir = (config: string, session: string): string =>
  `${config}/kodflow/sessions/${safe(session)}`;

export const tasksFile = (dir: string): string => `${dir}/tasks.json`;
export const agentsFile = (dir: string): string => `${dir}/agents.json`;
export const triageFile = (dir: string): string => `${dir}/triage-pending`;
export const beatFile = (dir: string): string => `${dir}/mod-beat`;

/** The beat's content: the time in whole seconds, as the shell compares it. */
export const beatText = (nowMs: number): string =>
  String(Math.floor(nowMs / 1000));

/**
 * When the user last typed at the prompt, in whole seconds: written on every
 * composer prompt, read by on-stop.sh before it proposes agent feedback.
 */
export const composerFile = (dir: string): string => `${dir}/composer-at`;

/** The merge gate's token for one call (L5): the head SHA it was agreed on. */
export const mergeTokenFile = (dir: string, toolUseId: unknown): string =>
  `${dir}/merge-ok/${safe(toolUseId)}`;

files.hooks/mod/machine-guards.ts:
// machine-guards.ts — modwall, collision-guard and zsh-safe, over a port.
//
// The engine follows `$` and `on` only inside register.ts, so register.ts
// builds a GuardPort from `$` and hooks the events; what each hook does is
// here, and the decisions themselves in modwall.ts, collision.ts and zsh.ts.
//
// Every guard fails open, as every kodflow hook does: a judge that throws
// lets the module load, a collision check that throws lets the edit through,
// a zsh setup that throws leaves the shell as it was.
import { safe, sessionDir, beatFile } from "./paths.ts";
import { decision, remember, report, type Decision } from "./modwall.ts";
import {
  CANCEL,
  CONTINUE,
  WORKTREE,
  answer,
  editsFile,
  excluded,
  isLive,
  newest,
  present,
  question,
  record,
  targetOf,
} from "./collision.ts";
import { zdotdirOf, zdotdirPlan } from "./zsh.ts";

const STORE_KEY = "modwall";

export type GuardPort = {
  /** KODFLOW_MOD=off */
  off: () => Promise<boolean>;
  /** The absolute Claude configuration directory, when there is one. */
  config: () => Promise<string | undefined>;
  read: (path: string) => Promise<string | undefined>;
  write: (path: string, text: string) => Promise<void>;
  list: (path: string) => Promise<{ name: string; kind: string }[]>;
  session: () => Promise<string>;
  cwd: () => Promise<string>;
  ask: (question: string, options: string[]) => Promise<string>;
  storeGet: (key: string) => Promise<unknown>;
  storeSet: (key: string, value: unknown) => Promise<void>;
  log: (text: string) => void;
  toast: (text: string) => void;
  /** Declares /kodflow-mods. */
  registerMods: (description: string) => Promise<unknown>;
  zdotdir: () => Promise<string | undefined>;
  userZdotdir: () => Promise<string | undefined>;
  setZdotdir: (value: string) => Promise<void>;
  setUserZdotdir: (value: string) => Promise<void>;
  pluginRoot: string;
  now: () => number;
};

const sec = (p: GuardPort) => Math.floor(p.now() / 1000);

// The modules judged since this one loaded, for /kodflow-mods
const judged: Decision[] = [];

// Refusals made before the session bound (a toast then is dropped), shown
// at session.start
const unshown: string[] = [];

// When the user last typed a prompt at the terminal (origin `composer`)
let lastComposerMs: number | undefined;

// What that prompt said, until a merge took it as its written consent
let lastComposerText: string | undefined;

/**
 * prompt.submit: remember a prompt the user typed, for the presence rule
 * and the merge gate's written consent. Any other origin (a notification, a
 * subagent's message) changes nothing.
 */
export function notePrompt(
  origin: unknown,
  nowMs: number,
  text?: unknown,
): void {
  if ((origin as { kind?: unknown } | undefined)?.kind !== "composer") return;
  lastComposerMs = nowMs;
  lastComposerText = typeof text === "string" ? text : undefined;
}

/** When the user last typed a prompt at the terminal, for any presence rule. */
export const lastComposerAt = (): number | undefined => lastComposerMs;

/** The last prompt typed at the terminal, unless a merge already used it. */
export const lastComposerPrompt = (): string | undefined => lastComposerText;

/** A merge used the last prompt as its consent: it serves no other. */
export const consumeComposerPrompt = (): void => {
  lastComposerText = undefined;
};

// A collision the user chose to go past: path -> the foreign edit's time.
// A newer edit by the other session asks again.
const acknowledged = new Map<string, number>();

// One write of edits.tsv at a time: the main loop and its subagents share
// this process and this session's file.
let writing: Promise<unknown> = Promise.resolve();

/**
 * modwall, on plugin.register: every module that joins after this one
 * passes here; only the user tier is judged, and only *@kodflow admitted.
 */
export async function admit(
  p: GuardPort,
  e: { name: string; tier: string; provenance: string },
): Promise<{ refuse: string } | undefined> {
  if (await p.off()) return undefined;
  const d = decision(e, sec(p));
  judged.push(d);
  try {
    if (d.reason) {
      p.log(d.reason);
      unshown.push(`modwall refused ${d.provenance}`);
    }
    await p.storeSet(STORE_KEY, remember(await p.storeGet(STORE_KEY), d));
  } catch {
    // the journal is best effort; the verdict stands
  }
  return d.reason ? { refuse: d.reason } : undefined;
}

/** What /kodflow-mods prints. */
export async function modsReport(p: GuardPort): Promise<string> {
  const history = await p.storeGet(STORE_KEY).catch(() => undefined);
  return report(judged, Array.isArray(history) ? history : []);
}

/** session.start's share: /kodflow-mods, and zsh-safe's ZDOTDIR. */
export async function startGuards(p: GuardPort): Promise<void> {
  if (await p.off()) return;
  for (const text of unshown.splice(0)) p.toast(text);
  await p
    .registerMods(
      "kodflow: the mods judged at load and the ones modwall refused",
    )
    .catch(() => undefined);
  try {
    const plan = zdotdirPlan(
      await p.zdotdir(),
      await p.userZdotdir(),
      zdotdirOf(p.pluginRoot),
    );
    if (plan) {
      await p.setUserZdotdir(plan.user);
      await p.setZdotdir(plan.zdotdir);
    }
  } catch {
    // the shell stays as the user has it
  }
}

async function others(
  p: GuardPort,
  cfg: string,
  self: string,
): Promise<{ session: string; text: string | undefined }[]> {
  const root = `${cfg}/kodflow/sessions`;
  const entries = await p.list(root).catch(() => []);
  const now = sec(p);
  const found = await Promise.all(
    entries
      .filter((d) => d.kind === "dir" && d.name !== self)
      .map(async (d) => {
        const dir = `${root}/${d.name}`;
        const text = await p.read(editsFile(dir));
        if (!text) return undefined;
        return isLive(await p.read(beatFile(dir)), now)
          ? { session: d.name, text }
          : undefined;
      }),
  );
  return found.filter((x) => x !== undefined);
}

async function noteEdit(p: GuardPort, dir: string, path: string) {
  const step = writing.then(async () => {
    const file = editsFile(dir);
    await p.write(file, record(await p.read(file), path, sec(p)));
  });
  writing = step.catch(() => undefined);
  await step;
}

/**
 * collision-guard, on tool.call of a writing tool: has another live session
 * of this machine written this file in the last 30 minutes? Ask; then, once
 * the write went through, note it in this session's edits.tsv.
 */
export async function guardWrite<R>(
  p: GuardPort,
  e: Record<string, unknown>,
  next: () => Promise<R>,
): Promise<R | { deny: string }> {
  if (await p.off()) return next();
  const path = targetOf(e.tool, e, await p.cwd());
  const cfg = await p.config();
  if (path === undefined || !cfg || excluded(path, cfg)) return next();
  const self = safe(await p.session());
  const now = sec(p);
  const hit = await others(p, cfg, self).then(
    (o) => newest(path, o, now),
    () => undefined,
  );
  if (
    hit &&
    hit.at > (acknowledged.get(path) ?? 0) &&
    !present(lastComposerMs, p.now())
  ) {
    // Nobody typed a prompt lately: asking would hold the edit until someone
    // comes back. Journaled, and the edit goes on.
    p.log(
      `collision-guard: ${path} edited by session ${hit.session} at ${hit.at}; no prompt typed in 10 min, not asked, the edit goes on`,
    );
  } else if (hit && hit.at > (acknowledged.get(path) ?? 0)) {
    // The dialog dismissed, or no one to ask after all: the edit goes on
    const chosen = await p
      .ask(question(path, hit, now), [CONTINUE, WORKTREE, CANCEL])
      .catch(() => undefined);
    p.log(
      `collision-guard: ${path} edited by session ${hit.session} at ${hit.at}; answer: ${chosen ?? "none, the edit goes on"}`,
    );
    if (chosen !== undefined) {
      const verdict = answer(chosen, path);
      if ("deny" in verdict) return verdict;
      acknowledged.set(path, hit.at);
    }
  }
  const r: any = await next();
  if (!r?.deny && !r?.isError)
    await noteEdit(p, sessionDir(cfg, self), path).catch(() => undefined);
  return r;
}

/**
 * session.end: this session's edits stop counting at once, rather than when
 * its beat ages out of the window.
 */
export async function endGuards(p: GuardPort): Promise<void> {
  const cfg = await p.config();
  if (!cfg) return;
  const file = editsFile(sessionDir(cfg, safe(await p.session())));
  if ((await p.read(file)) !== undefined) await p.write(file, "");
}

files.hooks/mod/shell.ts:
// shell.ts — what a Bash line will actually run. Pure.
//
// A port of the shell reader of hooks/scripts/on-tool.sh (_p_scan, _p_paren,
// _p_argv, _p_expand, _p_parse, _p_file), step for step, so the mod and the
// shell hook read a line the same way: the bash-guard corpus
// (tests/fixtures/bash-guard.jsonl) is replayed against both.
//
// It does the shell's own first pass: cuts the line into simple commands,
// removes quotes and backslashes, joins `\`+newline, sets heredoc bodies
// aside as data, and queues for another pass every text the shell would
// itself run ($( ), backticks, <( ), bash -c, sh -c, eval, su/sg -c, and a
// body or a pipe fed to a shell). It never expands a variable or an alias.

/** One simple command: its words, its stdin, its redirection targets. */
export type Command = {
  words: string[];
  /** What it reads on stdin: heredoc bodies and here-strings. */
  stdin: string;
  /** Redirection targets (`> f`, `< f`, `&> f`). */
  redirs: string[];
  /** True when a pipe feeds it. */
  pipe: boolean;
  /** Nesting depth of the text it was read from (0: the line itself). */
  depth: number;
};

export type Parsed = { commands: Command[]; nested: boolean };

const QUEUE_MAX = 64;
const DEPTH_MAX = 6;
const WORD = /[A-Za-z0-9_./:@%+,=-]/;

/** The content of a parenthesis opened just before `start`, and the index past `)`. */
function paren(t: string, start: number): { cap: string; end: number } {
  let k = start;
  let dep = 1;
  const m = t.length;
  while (k < m) {
    const ch = t[k]!;
    if (ch === "\\") {
      k += 2;
      continue;
    }
    if (ch === "'") {
      const close = t.indexOf("'", k + 1);
      const r = close < 0 ? t.slice(k + 1) : t.slice(k + 1, close);
      k += r.length + 2;
      continue;
    }
    if (ch === '"') {
      k++;
      while (k < m) {
        const c = t[k]!;
        if (c === "\\") {
          k += 2;
          continue;
        }
        if (c === '"') break;
        k++;
      }
    } else if (ch === "(") dep++;
    else if (ch === ")") {
      dep--;
      if (dep === 0) break;
    }
    k++;
  }
  return { cap: t.slice(start, k), end: k + 1 };
}

/** bash's printf %b on the body of a $'…' string. */
export function ansiC(raw: string): string {
  const simple: Record<string, string> = {
    a: "\x07",
    b: "\b",
    e: "\x1b",
    E: "\x1b",
    f: "\f",
    n: "\n",
    r: "\r",
    t: "\t",
    v: "\v",
    "\\": "\\",
    "'": "'",
    '"': '"',
  };
  let out = "";
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i]!;
    if (c !== "\\" || i + 1 >= raw.length) {
      out += c;
      continue;
    }
    const n = raw[i + 1]!;
    if (n in simple) {
      out += simple[n];
      i++;
    } else if (n === "x") {
      const hex = /^[0-9A-Fa-f]{1,2}/.exec(raw.slice(i + 2));
      if (hex) {
        out += String.fromCharCode(parseInt(hex[0], 16));
        i += 1 + hex[0].length;
      } else out += c;
    } else if (n === "u" || n === "U") {
      const hex = (n === "u" ? /^[0-9A-Fa-f]{1,4}/ : /^[0-9A-Fa-f]{1,8}/).exec(
        raw.slice(i + 2),
      );
      if (hex) {
        out += String.fromCodePoint(parseInt(hex[0], 16));
        i += 1 + hex[0].length;
      } else out += c;
    } else if (n === "0") {
      const oct = /^[0-7]{0,3}/.exec(raw.slice(i + 2))![0];
      out += String.fromCharCode(parseInt(oct || "0", 8) & 0xff);
      i += 1 + oct.length;
    } else if (/[1-7]/.test(n)) {
      const oct = /^[0-7]{1,3}/.exec(raw.slice(i + 1))![0];
      out += String.fromCharCode(parseInt(oct, 8) & 0xff);
      i += oct.length;
    } else if (n === "c") break;
    else out += c;
  }
  return out;
}

class Reader {
  readonly cmds: Command[] = [];
  /** stdin gathered for an index before (or after) its command is closed. */
  private readonly pendingIn = new Map<number, string>();
  readonly queue: { text: string; depth: number }[] = [];

  push(text: string, depth: number): void {
    if (this.queue.length < QUEUE_MAX && depth <= DEPTH_MAX)
      this.queue.push({ text, depth });
  }

  private addIn(index: number, text: string): void {
    const cmd = this.cmds[index];
    if (cmd) cmd.stdin += text;
    else this.pendingIn.set(index, (this.pendingIn.get(index) ?? "") + text);
  }

  scan(s: string, d: number): void {
    const n = s.length;
    let i = 0;
    let w = "";
    let wa = false;
    let rn = 0;
    let cw: string[] = [];
    let cr: string[] = [];
    let pipe = false;
    let hq: { idx: number; strip: boolean; dl: string }[] = [];

    const pw = () => {
      if (wa) {
        if (rn === 1) cr.push(w);
        else if (rn === 2) this.addIn(this.cmds.length, `${w}\n`);
        else cw.push(w);
        rn = 0;
      }
      w = "";
      wa = false;
    };
    const pc = (nextPipe = false) => {
      pw();
      const idx = this.cmds.length;
      const pending = this.pendingIn.get(idx) ?? "";
      if (cw.length || cr.length || pending) {
        this.pendingIn.delete(idx);
        this.cmds.push({
          words: cw,
          stdin: pending,
          redirs: cr,
          pipe,
          depth: d,
        });
      }
      cw = [];
      cr = [];
      pipe = nextPipe;
    };
    const dollar = () => {
      const p = paren(s, i + 2);
      if (s[i + 2] !== "(") this.push(p.cap, d + 1);
      w += `$(${p.cap})`;
      wa = true;
      i = p.end;
    };
    const tick = () => {
      let k = i + 1;
      while (k < n) {
        const ch = s[k]!;
        if (ch === "\\") {
          k += 2;
          continue;
        }
        if (ch === "`") break;
        k++;
      }
      this.push(s.slice(i + 1, k), d + 1);
      w += s.slice(i, k + 1);
      wa = true;
      i = k + 1;
    };

    while (i < n) {
      const c = s[i]!;
      if (WORD.test(c)) {
        w += c;
        wa = true;
        i++;
        continue;
      }
      switch (c) {
        case " ":
        case "\t":
          pw();
          break;
        case "\n":
          pc();
          if (hq.length) {
            i++;
            for (const q of hq) {
              let body = "";
              while (i < n) {
                const nl = s.indexOf("\n", i);
                let line = nl < 0 ? s.slice(i) : s.slice(i, nl);
                i += line.length + 1;
                if (q.strip) line = line.replace(/^\t+/, "");
                if (line === q.dl) break;
                body += `${line}\n`;
              }
              this.addIn(q.idx, body);
            }
            hq = [];
            continue;
          }
          break;
        case ";":
        case "(":
        case ")":
          pc();
          break;
        case "&":
          if (s[i + 1] === ">") {
            pw();
            i += 2;
            if (s[i] === ">") i++;
            rn = 1;
            continue;
          }
          if (s[i + 1] === "&") i++;
          pc();
          break;
        case "|":
          if (s[i + 1] === "|") {
            i++;
            pc();
          } else if (s[i + 1] === "&") {
            i++;
            pc(true);
          } else pc(true);
          break;
        case "<":
        case ">": {
          if (wa) {
            if (/[^0-9]/.test(w)) pw();
            else {
              w = "";
              wa = false;
            }
          }
          if (c === "<" && s.slice(i + 1, i + 3) === "<<") {
            i += 3;
            rn = 2;
            continue;
          }
          if (c === "<" && s[i + 1] === "<") {
            i += 2;
            let strip = false;
            if (s[i] === "-") {
              strip = true;
              i++;
            }
            while (s[i] === " " || s[i] === "\t") i++;
            let dl = "";
            while (i < n) {
              const ch = s[i]!;
              if (" \t\n;&|<>()".includes(ch)) break;
              if (ch === "'" || ch === '"') {
                const close = s.indexOf(ch, i + 1);
                const r = close < 0 ? s.slice(i + 1) : s.slice(i + 1, close);
                dl += r;
                i += r.length + 2;
                continue;
              }
              if (ch === "\\") {
                dl += s[i + 1] ?? "";
                i += 2;
                continue;
              }
              dl += ch;
              i++;
            }
            hq.push({ idx: this.cmds.length, strip, dl });
            continue;
          }
          if (s[i + 1] === "(") {
            const p = paren(s, i + 2);
            this.push(p.cap, d + 1);
            i = p.end;
            continue;
          }
          i++;
          const nx = s[i];
          if (nx === ">" || nx === "|") i++;
          else if (nx === "&") {
            i++;
            while (i < n && /[0-9-]/.test(s[i]!)) i++;
            continue;
          }
          if (c === "<" && s[i] === ">") i++;
          rn = 1;
          continue;
        }
        case "#":
          if (!wa) {
            const nl = s.indexOf("\n", i);
            i = nl < 0 ? n : nl;
            continue;
          }
          w += c;
          break;
        case "\\":
          if (s[i + 1] === "\n") {
            i += 2;
            continue;
          }
          w += s[i + 1] ?? "";
          wa = true;
          i += 2;
          continue;
        case "'": {
          const close = s.indexOf("'", i + 1);
          const r = close < 0 ? s.slice(i + 1) : s.slice(i + 1, close);
          w += r;
          wa = true;
          i += r.length + 2;
          continue;
        }
        case '"': {
          i++;
          wa = true;
          while (i < n) {
            const ch = s[i]!;
            if (ch === '"') break;
            if (ch === "\\") {
              const nx = s[i + 1];
              if (nx === "\n") {
                i += 2;
                continue;
              }
              if (nx === '"' || nx === "\\" || nx === "$" || nx === "`") {
                w += nx;
                i += 2;
                continue;
              }
            } else if (ch === "$" && s[i + 1] === "(") {
              dollar();
              continue;
            } else if (ch === "`") {
              tick();
              continue;
            }
            w += ch;
            i++;
          }
          break;
        }
        case "$":
          if (s[i + 1] === "(") {
            dollar();
            continue;
          }
          if (s[i + 1] === "'") {
            i += 2;
            let r = "";
            while (i < n) {
              const ch = s[i]!;
              if (ch === "'") break;
              if (ch === "\\") {
                r += s.slice(i, i + 2);
                i += 2;
                continue;
              }
              r += ch;
              i++;
            }
            w += ansiC(r);
            wa = true;
          } else {
            w += c;
            wa = true;
          }
          break;
        case "`":
          tick();
          continue;
        default:
          w += c;
          wa = true;
      }
      i++;
    }
    pc();
  }
}

/** Every simple command the line runs, nested ones included. */
export function parse(line: string): Parsed {
  const r = new Reader();
  r.push(line, 0);
  for (let qi = 0; qi < r.queue.length; qi++) {
    const { text, depth } = r.queue[qi]!;
    const from = r.cmds.length;
    r.scan(text, depth);
    for (let k = from; k < r.cmds.length; k++) expand(r, k, depth);
  }
  return { commands: r.cmds, nested: r.queue.length > 1 };
}

export type Argv = {
  /** argv from the executable on, wrappers and assignments walked past. */
  argv: string[];
  /** The executable's basename (`lookup` for `command -v`). */
  name: string;
  /** NAME=value words before it, wrappers' own included. */
  assigns: Record<string, string>;
};

const RESERVED = new Set([
  "!",
  "{",
  "}",
  "if",
  "then",
  "else",
  "elif",
  "do",
  "while",
  "until",
]);
const isAssign = (t: string) => /^[A-Za-z_][^=]*=/.test(t);
const validName = (t: string) => /^[A-Za-z0-9_]*$/.test(t.split("=")[0]!);
const base = (t: string) => {
  const s = t.replace(/^=/, "");
  return s.slice(s.lastIndexOf("/") + 1);
};

/** The command's argv, as on-tool.sh's _p_argv reads it. */
export function argvOf(cmd: Command): Argv {
  const W = cmd.words;
  const nw = W.length;
  const assigns: Record<string, string> = {};
  let x = 0;
  while (x < nw) {
    const t = W[x]!;
    if (RESERVED.has(t)) {
      x++;
      continue;
    }
    if (isAssign(t) && validName(t)) {
      const eq = t.indexOf("=");
      assigns[t.slice(0, eq)] = t.slice(eq + 1);
      x++;
      continue;
    }
    const name = base(t);
    if (name === "env") {
      x++;
      while (x < nw) {
        const v = W[x]!;
        if (["-u", "-C", "-S", "--unset", "--chdir"].includes(v)) x += 2;
        else if (v.startsWith("-")) x++;
        else if (isAssign(v)) {
          const eq = v.indexOf("=");
          assigns[v.slice(0, eq)] = v.slice(eq + 1);
          x++;
        } else break;
      }
    } else if (
      [
        "command",
        "builtin",
        "nohup",
        "chronic",
        "exec",
        "time",
        "caffeinate",
      ].includes(name)
    ) {
      x++;
      while (x < nw) {
        const v = W[x]!;
        if (name === "command" && (v === "-v" || v === "-V"))
          return { argv: [], name: "lookup", assigns };
        if (name === "exec" && v === "-a") x += 2;
        else if (v.startsWith("-")) x++;
        else break;
      }
    } else if (
      ["nice", "timeout", "ionice", "stdbuf", "doas", "sudo", "xargs"].includes(
        name,
      )
    ) {
      x++;
      while (x < nw) {
        const v = W[x]!;
        if (v === "--") {
          x++;
          break;
        }
        if (
          (name === "sudo" && /^-[ugChpUrtDR]$/.test(v)) ||
          (name === "doas" && /^-[uC]$/.test(v)) ||
          (name === "nice" && v === "-n") ||
          (name === "xargs" && /^-[InPLsdEa]$/.test(v)) ||
          (name === "timeout" && /^-[sk]$/.test(v)) ||
          (name === "ionice" && /^-[cnp]$/.test(v))
        )
          x += 2;
        else if (v.startsWith("-")) x++;
        else break;
      }
      if (name === "timeout") x++;
    } else if (name === "rtk") {
      x++;
      if (W[x] === "proxy") x++;
    } else break;
  }
  const argv = W.slice(x);
  return { argv, name: argv[0] === undefined ? "" : base(argv[0]), assigns };
}

const SHELLS = new Set(["bash", "sh", "zsh", "dash", "ksh", "ash", "mksh"]);

/** Queue what command k hands to a shell. */
function expand(r: Reader, k: number, depth: number): void {
  const cmd = r.cmds[k]!;
  const { argv: A, name } = argvOf(cmd);
  if (SHELLS.has(name)) {
    let y = 1;
    while (y < A.length) {
      const v = A[y]!;
      if (v === "-o" || v === "+o") {
        y += 2;
        continue;
      }
      if (v.startsWith("--")) {
        /* a long option */
      } else if (v.startsWith("-") && v.includes("c")) {
        r.push(A[y + 1] ?? "", depth + 1);
        return;
      } else if (v.startsWith("-") || v.startsWith("+")) {
        /* an option */
      } else return; // a script file: not ours to read
      y++;
    }
    if (cmd.stdin) r.push(cmd.stdin, depth + 1);
    if (cmd.pipe && k > 0) {
      const prev = r.cmds[k - 1]!;
      if (prev.stdin) r.push(prev.stdin, depth + 1);
      const p = argvOf(prev);
      if (p.name === "echo" || p.name === "printf")
        r.push(p.argv.slice(1).join(" "), depth + 1);
    }
  } else if (name === "eval") {
    if (A.length > 1) r.push(A.slice(1).join(" "), depth + 1);
  } else if (name === "su" || name === "sg") {
    for (let y = 1; y < A.length; y++)
      if (A[y] === "-c") {
        r.push(A[y + 1] ?? "", depth + 1);
        return;
      }
  }
}

/**
 * The text a file argument of command k stands for: `-` its stdin (and what a
 * pipe feeds it), a file on disk through `read`, else what an earlier
 * redirection on the same line wrote there.
 */
export async function fileText(
  p: Parsed,
  k: number,
  f: string,
  read: (path: string) => Promise<string | undefined>,
): Promise<string> {
  const cmds = p.commands;
  const fed = (j: number) => {
    const a = argvOf(cmds[j]!);
    return a.name === "echo" || a.name === "printf"
      ? `${a.argv.slice(1).join(" ")}\n`
      : "";
  };
  if (f === "-") {
    let out = cmds[k]?.stdin ?? "";
    if (cmds[k]?.pipe && k > 0) out += (cmds[k - 1]!.stdin ?? "") + fed(k - 1);
    return out;
  }
  if (!f) return "";
  const disk = await read(f).catch(() => undefined);
  if (disk !== undefined) return disk.slice(0, 200_000);
  let out = "";
  cmds.forEach((c, j) => {
    if (c.redirs.includes(f)) out += c.stdin + fed(j);
  });
  return out;
}

