// guards.ts — the shell's Bash guards, doubled in the mod (L4). No `$`.
//
// on-tool.sh stays the authority (D1); this is a second copy that only ever
// refuses, for a session where the shell hook is missing, edited or slow.
// Same reader (shell.ts), same order of blocks, same motifs, so the
// bash-guard corpus decides both the same way (tests/mod/guards.corpus.ts).
//
// Not doubled: the staged-secret scan (BLOCK 3), which reads the index blob
// by blob and stays the shell's alone. The mcp.json refusal of the same block
// is doubled: it reads the index once, by name and status only.
import { argvOf, fileText, parse, type Parsed } from "./shell.ts";
import { scan, type Hit, type Kind, type Rules } from "./patterns.ts";

export type GuardCtx = {
  /** Set when a subagent makes the call. */
  agentId?: string;
  /** The delegation gate applies: main thread, KODFLOW_ROOT not off. */
  rootMain: boolean;
  /** The session's directory, against which relative paths resolve. */
  projectDir: string;
  home?: string;
  /** <config> (CLAUDE_CONFIG_DIR, else ~/.claude). */
  configDir?: string;
  /** A file's text, undefined when absent; relative to projectDir. */
  read(path: string): Promise<string | undefined>;
  /** `git -C dir …`'s stdout, undefined on failure. */
  git(dir: string, args: string[]): Promise<string | undefined>;
  /** Main thread only: the merge holds a token (L5) or an exemption. */
  mergeAllowed(): Promise<boolean>;
  /** The vendored §5 rules (hooks/patterns), undefined when unreadable. */
  patterns(): Promise<Rules | undefined>;
};

export type Findings = {
  root?: string;
  noVerify?: string;
  attr?: Hit;
  commit: boolean;
  force: boolean;
  merge?: string;
  defaultPush?: string;
  modWrite?: string;
  plugin?: string;
  /** An mcp.json added or committed, and how. */
  mcpJson?: string;
};

export type Refusal = { motif: string; title: string; lines: string[] };

const isNoVerify = (v: string) =>
  v === "--no-veri" || v === "--no-verif" || v === "--no-verify";

export const MERGE_RE =
  /(^|\/)pulls\/[^/\s]+\/merge\/?$|merge_requests\/[^/\s]+\/merge\/?$/;
export const MERGE_WORDS =
  /mergePullRequest|enablePullRequestAutoMerge|merge_when_pipeline_succeeds/;

/** mcp.json or .mcp.json, any case, at any path: it may carry tokens. */
export const isMcpJson = (path: string) => /(^|\/)\.?mcp\.json$/i.test(path);

/**
 * `git diff --name-status -z` → the paths it adds or changes; a deletion is
 * left out, and a rename or a copy gives its new path.
 */
export function changedPaths(out: string): string[] {
  const w = out.split("\0");
  const paths: string[] = [];
  for (let i = 0; i + 1 < w.length; ) {
    const st = w[i]!;
    if (!st) break;
    const two = st[0] === "R" || st[0] === "C";
    const path = w[i + (two ? 2 : 1)] ?? "";
    if (st[0] !== "D") paths.push(path);
    i += two ? 3 : 2;
  }
  return paths;
}

/** The refusal of an mcp.json added or committed (BLOCK 3 of on-tool.sh). */
export function mcpJsonRefusal(what: string): Refusal {
  return {
    motif: "mcp-json",
    title: `BLOCKED — an mcp.json file is never committed (${what})`,
    lines: [
      "mcp.json and .mcp.json may carry tokens: neither is added nor committed, at any path.",
      "Deleting one stays allowed: git rm --cached <path>, then commit the deletion.",
      "A plugin declares its MCP servers in plugin.json (mcpServers), not in a .mcp.json.",
    ],
  };
}

type SpecMode = "add" | "add-f" | "update" | "commit";

/**
 * The first mcp.json a set of pathspecs would take in, a deletion left out.
 * git status resolves them as git add and git commit do ("XY path", the old
 * path after a rename; Y is the working tree). add-f lists ignored files too.
 */
async function mcpJsonSpecs(
  ctx: Pick<GuardCtx, "git">,
  dir: string,
  mode: SpecMode,
  specs: string[],
): Promise<string | undefined> {
  const opt =
    mode === "update" || mode === "commit"
      ? ["--untracked-files=no"]
      : mode === "add-f"
        ? ["--untracked-files=all", "--ignored"]
        : ["--untracked-files=all"];
  const w = (
    (await ctx.git(dir, ["status", "--porcelain", "-z", ...opt, "--", ...specs])) ?? ""
  ).split("\0");
  for (let i = 0; i < w.length; i++) {
    const e = w[i]!;
    if (e.length < 4) continue;
    const x = e[0]!;
    const y = e[1]!;
    const f = e.slice(3);
    if (x === "R" || x === "C") i++;
    if (!isMcpJson(f) || y === "D") continue;
    // staged already: only a commit takes it
    if (y === " " && (mode !== "commit" || x === "D" || x === " ")) continue;
    return f;
  }
  return undefined;
}

/** A --pathspec-from-file's pathspecs, one a line. */
async function specsFrom(
  ctx: GuardCtx,
  p: Parsed,
  k: number,
  file: string,
  gdir: string,
): Promise<string[]> {
  const f = file === "-" || file.startsWith("/") ? file : `${gdir}/${file}`;
  return (await fileText(p, k, f, ctx.read)).split("\n").filter(Boolean);
}

/** A path a skills directory must never receive (plugin machinery). */
export function modPath(
  path: string,
  home: string | undefined,
  configDir: string | undefined,
): boolean {
  let f = path;
  const cfg = (configDir || `${home ?? ""}/.claude`).replace(/\/+$/, "");
  if (f.startsWith("~/")) f = `${home ?? ""}/${f.slice(2)}`;
  f = `/${f.replace(/^\//, "")}`;
  if (!(f.includes("/.claude/skills/") || f.startsWith(`${cfg}/skills/`)))
    return false;
  return (
    f.includes("/.claude-plugin/") ||
    f.endsWith("/.claude-plugin") ||
    f.endsWith("/hooks/hooks.json")
  );
}

type State = {
  f: Findings;
  gdir: string;
  hooks: boolean;
  amend: boolean;
  /** git commit -a: the tracked changes are staged first. */
  all: boolean;
  /** The repository the commit runs in. */
  cgdir: string;
  scan: (kind: Kind, text: string) => Hit | undefined;
};

function hit(st: State, h: Hit | undefined): void {
  if (!st.f.attr && h) st.f.attr = h;
}

async function defaults(ctx: GuardCtx, dir: string): Promise<Set<string>> {
  const set = new Set(["main", "master"]);
  const h = await ctx.git(dir, [
    "symbolic-ref",
    "--short",
    "refs/remotes/origin/HEAD",
  ]);
  if (h) set.add(h.trim().replace(/^origin\//, ""));
  return set;
}

async function guardPush(
  ctx: GuardCtx,
  st: State,
  A: string[],
  y0: number,
  gdir: string,
): Promise<void> {
  let pos = 0;
  const refs: string[] = [];
  let force = false;
  let all = false;
  for (let y = y0; y < A.length; y++) {
    const v = A[y]!;
    if (
      v.startsWith("--force-with-lease") ||
      v === "--force-if-includes" ||
      v.startsWith("--no-force-")
    ) {
      /* safe */
    } else if (v === "--force") force = true;
    else if (v === "--mirror" || v === "--all" || v === "--branches")
      all = true;
    else if (
      ["--repo", "--receive-pack", "--exec", "--push-option", "-o"].includes(v)
    )
      y++;
    else if (v.startsWith("--")) {
      if (isNoVerify(v)) st.f.noVerify = "--no-verify on git push";
    } else if (v.startsWith("-")) {
      if (v.includes("f")) force = true;
    } else {
      pos++;
      if (pos >= 2) refs.push(v);
      if (v.startsWith("+") && pos >= 2) force = true;
    }
  }
  if (force) st.f.force = true;
  if (!ctx.agentId) return;
  const defs = await defaults(ctx, gdir);
  if (all) {
    st.f.defaultPush = "git push --all/--mirror includes the default branch";
    return;
  }
  const current = async () =>
    (await ctx.git(gdir, ["symbolic-ref", "--short", "HEAD"]))?.trim() ?? "";
  if (!refs.length) {
    const cur = await current();
    if (cur && defs.has(cur))
      st.f.defaultPush = `git push from ${cur}, the default branch`;
    return;
  }
  for (let r of refs) {
    r = r.replace(/^\+/, "");
    let dst = r.includes(":") ? r.slice(r.indexOf(":") + 1) : r;
    if (dst === "HEAD" || r === "HEAD") dst = await current();
    dst = dst.replace(/^refs\/heads\//, "");
    if (dst && defs.has(dst))
      st.f.defaultPush = `git push to ${dst}, the default branch`;
  }
}

async function guardGit(
  ctx: GuardCtx,
  st: State,
  p: Parsed,
  k: number,
  A: string[],
): Promise<void> {
  let y = 1;
  let gdir = st.gdir;
  st.hooks = false;
  while (y < A.length) {
    const v = A[y]!;
    if (v === "-C") {
      // joined onto the cd directory, as git does
      const c = A[y + 1] ?? "";
      gdir = c.startsWith("/") || !gdir ? c : `${gdir}/${c}`;
      y += 2;
      continue;
    }
    if (v === "-c" || v === "--config-env") {
      if ((A[y + 1] ?? "").toLowerCase().startsWith("core.hookspath="))
        st.hooks = true;
      y += 2;
      continue;
    }
    if (v.startsWith("--config-env=")) {
      if (v.toLowerCase().includes("=core.hookspath=")) st.hooks = true;
    } else if (
      ["--git-dir", "--work-tree", "--namespace", "--super-prefix"].includes(v)
    ) {
      y += 2;
      continue;
    } else if (!v.startsWith("-")) break;
    y++;
  }
  if (!gdir) gdir = ctx.projectDir;
  else if (!gdir.startsWith("/")) gdir = `${ctx.projectDir}/${gdir}`;
  const sub = A[y] ?? "";
  y++;
  const rest = A.slice(y);
  if (
    [
      "commit",
      "push",
      "rebase",
      "cherry-pick",
      "merge",
      "am",
      "apply",
      "revert",
    ].includes(sub)
  )
    st.f.root = `git ${sub} from the main thread produces into a repository.`;
  else if (sub === "worktree" && A[y] === "add")
    st.f.root = "git worktree from the main thread produces into a repository.";
  else if (sub === "reset" && rest.includes("--hard"))
    st.f.root = "git reset from the main thread produces into a repository.";
  if (
    st.hooks &&
    [
      "commit",
      "push",
      "merge",
      "am",
      "rebase",
      "cherry-pick",
      "revert",
      "pull",
    ].includes(sub)
  )
    st.f.noVerify = `git -c core.hooksPath on git ${sub}`;

  if (sub === "add" || sub === "stage") {
    // Every word but an option's names a pathspec, -f or not; then git
    // status says what `.`, a directory, a glob or -A would take in
    let mode: SpecMode = "add";
    let all = false;
    const specs: string[] = [];
    while (y < A.length) {
      const v = A[y]!;
      if (v === "--pathspec-from-file") {
        specs.push(...(await specsFrom(ctx, p, k, A[y + 1] ?? "", gdir)));
        y += 2;
        continue;
      }
      if (v.startsWith("--pathspec-from-file="))
        specs.push(...(await specsFrom(ctx, p, k, v.slice(21), gdir)));
      else if (v === "--all" || v === "--no-ignore-removal") all = true;
      else if (v === "--update") {
        all = true;
        if (mode === "add") mode = "update";
      } else if (v === "--force") mode = "add-f";
      else if (v.startsWith("--")) {
        /* another option */
      } else if (v.startsWith("-")) {
        if (v.includes("f")) mode = "add-f";
        if (v.includes("A")) all = true;
        if (v.includes("u")) {
          all = true;
          if (mode === "add") mode = "update";
        }
      } else {
        if (isMcpJson(v)) st.f.mcpJson = `git ${sub} ${v}`;
        specs.push(v);
      }
      y++;
    }
    if (!st.f.mcpJson && (specs.length || all)) {
      const f = await mcpJsonSpecs(ctx, gdir, mode, specs);
      if (f) st.f.mcpJson = `git ${sub} would add ${f}`;
    }
  } else if (sub === "commit") {
    st.f.commit = true;
    st.cgdir = gdir;
    const specs: string[] = [];
    let msg = "";
    let farg = "";
    let given = false;
    while (y < A.length) {
      const v = A[y]!;
      if (v === "--") {
        for (const w of A.slice(y + 1)) {
          if (isMcpJson(w)) st.f.mcpJson = `git commit ${w}`;
          specs.push(w);
        }
        break;
      }
      if (v === "--pathspec-from-file") {
        specs.push(...(await specsFrom(ctx, p, k, A[y + 1] ?? "", gdir)));
        y += 2;
        continue;
      }
      if (v.startsWith("--pathspec-from-file=")) {
        specs.push(...(await specsFrom(ctx, p, k, v.slice(21), gdir)));
        y++;
        continue;
      }
      if (v === "-m" || v === "--message" || v === "--trailer") {
        msg += `\n${A[y + 1] ?? ""}`;
        given = true;
        y += 2;
        continue;
      }
      if (v.startsWith("--message=") || v.startsWith("--trailer=")) {
        msg += `\n${v.slice(v.indexOf("=") + 1)}`;
        given = true;
      } else if (v === "-F" || v === "--file") {
        farg = A[y + 1] ?? "";
        y += 2;
        continue;
      } else if (v.startsWith("--file=")) farg = v.slice(7);
      else if (
        [
          "-C",
          "-c",
          "-t",
          "--reuse-message",
          "--reedit-message",
          "--author",
          "--date",
          "--cleanup",
          "--template",
          "--fixup",
          "--squash",
        ].includes(v)
      ) {
        y += 2;
        continue;
      } else if (v === "--amend") st.amend = true;
      else if (v === "--all") st.all = true;
      else if (v.startsWith("--")) {
        if (isNoVerify(v)) st.f.noVerify = "--no-verify on git commit";
      } else if (v.startsWith("-")) {
        let cl = v.slice(1);
        while (cl) {
          const ch = cl[0]!;
          let r = cl.slice(1);
          if (ch === "n") st.f.noVerify = "-n (--no-verify) on git commit";
          else if (ch === "a") st.all = true;
          else if (ch === "u" || ch === "S") break;
          else if ("mFCct".includes(ch)) {
            if (!r) {
              r = A[y + 1] ?? "";
              y++;
            }
            if (ch === "m") {
              msg += `\n${r}`;
              given = true;
            } else if (ch === "F") farg = r;
            break;
          }
          cl = r;
        }
      } else {
        // a pathspec
        if (isMcpJson(v)) st.f.mcpJson = `git commit ${v}`;
        specs.push(v);
      }
      y++;
    }
    // A pathspec (`.`, a directory) takes the working tree's copy in
    if (!st.f.mcpJson && specs.length) {
      const f = await mcpJsonSpecs(ctx, gdir, "commit", specs);
      if (f) st.f.mcpJson = `git commit ${specs.join(" ")} takes in ${f}`;
    }
    let hay = msg;
    if (farg) hay += `\n${await fileText(p, k, farg, ctx.read)}`;
    if (st.amend && !given && !farg)
      hay += `\n${(await ctx.git(gdir, ["log", "-1", "--pretty=%B"])) ?? ""}`;
    hit(st, st.scan("commit", hay));
  } else if (sub === "merge") {
    while (y < A.length) {
      const v = A[y]!;
      if (v === "-m") {
        hit(st, st.scan("commit", A[y + 1] ?? ""));
        y += 2;
        continue;
      }
      if (v === "-F" || v === "--file") {
        hit(st, st.scan("commit", await fileText(p, k, A[y + 1] ?? "", ctx.read)));
        y += 2;
        continue;
      }
      if (v.startsWith("--") && isNoVerify(v))
        st.f.noVerify = "--no-verify on git merge";
      y++;
    }
  } else if (sub === "rebase" || sub === "cherry-pick") {
    for (const v of rest)
      if (isNoVerify(v)) st.f.noVerify = `--no-verify on git ${sub}`;
    hit(
      st,
      st.scan("commit", (await ctx.git(gdir, ["log", "-5", "--pretty=%B"])) ?? ""),
    );
  } else if (sub === "am" || sub === "revert" || sub === "pull") {
    for (const v of rest)
      if (isNoVerify(v)) st.f.noVerify = `--no-verify on git ${sub}`;
  } else if (sub === "push") await guardPush(ctx, st, A, y, gdir);
}

async function guardGh(
  ctx: GuardCtx,
  st: State,
  p: Parsed,
  k: number,
  A: string[],
): Promise<void> {
  let y = 1;
  while (y < A.length) {
    const v = A[y]!;
    if (v === "-R" || v === "--repo" || v === "--hostname") y += 2;
    else if (v.startsWith("-")) y++;
    else break;
  }
  const sub = A[y] ?? "";
  const act = A[y + 1] ?? "";
  let hay = "";
  if (sub === "pr" && (act === "create" || act === "edit")) {
    if (act === "create")
      st.f.root =
        "gh pr create from the main thread: opening the PR is the subagent's delivery.";
    y += 2;
    while (y < A.length) {
      const v = A[y]!;
      if (["-t", "--title", "-b", "--body"].includes(v)) {
        hay += `\n${A[y + 1] ?? ""}`;
        y += 2;
        continue;
      }
      if (v.startsWith("--title=") || v.startsWith("--body="))
        hay += `\n${v.slice(v.indexOf("=") + 1)}`;
      else if (v === "-F" || v === "--body-file") {
        hay += `\n${await fileText(p, k, A[y + 1] ?? "", ctx.read)}`;
        y += 2;
        continue;
      } else if (v.startsWith("--body-file="))
        hay += `\n${await fileText(p, k, v.slice(12), ctx.read)}`;
      else if (
        [
          "-R",
          "--repo",
          "-B",
          "--base",
          "-H",
          "--head",
          "-a",
          "--assignee",
          "-l",
          "--label",
          "-m",
          "--milestone",
          "-p",
          "--project",
          "-r",
          "--reviewer",
          "-T",
          "--template",
        ].includes(v) ||
        v.startsWith("--add-") ||
        v.startsWith("--remove-")
      ) {
        y += 2;
        continue;
      }
      y++;
    }
    hit(st, st.scan("pr", hay));
  } else if (sub === "pr" && act === "merge") st.f.merge = "gh pr merge";
  else if (sub === "api") {
    let ep = "";
    y++;
    while (y < A.length) {
      const v = A[y]!;
      if (["-f", "--raw-field", "-F", "--field"].includes(v)) {
        const f = A[y + 1] ?? "";
        const at = f.indexOf("=@");
        hay +=
          at >= 0
            ? `\n${await fileText(p, k, f.slice(at + 2), ctx.read)}`
            : `\n${f.includes("=") ? f.slice(f.indexOf("=") + 1) : f}`;
        y += 2;
        continue;
      }
      if (v === "--input") {
        hay += `\n${await fileText(p, k, A[y + 1] ?? "", ctx.read)}`;
        y += 2;
        continue;
      }
      if (
        [
          "-X",
          "--method",
          "-H",
          "--header",
          "-q",
          "--jq",
          "-t",
          "--template",
          "-p",
          "--preview",
          "--hostname",
          "--cache",
        ].includes(v)
      ) {
        y += 2;
        continue;
      }
      if (!v.startsWith("-") && !ep) ep = v;
      y++;
    }
    if (MERGE_RE.test(ep)) st.f.merge = `gh api ${ep}`;
    else if (ep === "graphql") {
      const m = MERGE_WORDS.exec(hay);
      if (m) st.f.merge = `gh api graphql ${m[0]}`;
      if (/(create|update)PullRequest/.test(hay)) hit(st, st.scan("pr", hay));
    } else if (/(^|\/)pulls(\/[^/]+)?\/?$/.test(ep)) hit(st, st.scan("pr", hay));
  }
}

function guardGlab(st: State, A: string[]): void {
  let y = 1;
  while (y < A.length) {
    const v = A[y]!;
    if (v === "-R" || v === "--repo") y += 2;
    else if (v.startsWith("-")) y++;
    else break;
  }
  const sub = A[y] ?? "";
  const act = A[y + 1] ?? "";
  const words = MERGE_WORDS.exec(A.join(" "));
  if (words) st.f.merge = `glab ${words[0]}`;
  if (sub === "mr" && (act === "create" || act === "update")) {
    if (act === "create")
      st.f.root =
        "glab mr create from the main thread: opening the PR is the subagent's delivery.";
    let hay = "";
    y += 2;
    while (y < A.length) {
      const v = A[y]!;
      if (["-t", "--title", "-d", "--description"].includes(v)) {
        hay += `\n${A[y + 1] ?? ""}`;
        y += 2;
        continue;
      }
      if (v.startsWith("--title=") || v.startsWith("--description="))
        hay += `\n${v.slice(v.indexOf("=") + 1)}`;
      y++;
    }
    hit(st, st.scan("pr", hay));
  } else if (sub === "mr" && act === "merge") st.f.merge = "glab mr merge";
  else if (sub === "api") {
    y++;
    while (y < A.length) {
      const v = A[y]!;
      if (
        [
          "-X",
          "--method",
          "-H",
          "--header",
          "-f",
          "--raw-field",
          "-F",
          "--field",
          "--hostname",
          "--input",
        ].includes(v)
      ) {
        y += 2;
        continue;
      }
      if (!v.startsWith("-")) {
        if (MERGE_RE.test(v)) st.f.merge = `glab api ${v}`;
        break;
      }
      y++;
    }
  }
}

function guardHttp(st: State, name: string, A: string[]): void {
  for (const v of A.slice(1)) {
    const m = MERGE_RE.exec(v) ?? MERGE_WORDS.exec(v);
    if (m) {
      st.f.merge = `${name} ${m[0]}`;
      return;
    }
    if (/\/pulls\/[^/\s]+\/merge([/?\s]|$)/.test(v)) {
      st.f.merge = `${name} …/merge`;
      return;
    }
  }
}

function guardClaude(st: State, A: string[]): void {
  if (A[1] !== "plugin" && A[1] !== "plugins") return;
  let y: number;
  if (A[2] === "install" || A[2] === "i") y = 3;
  else if (A[2] === "marketplace" && A[3] === "add") y = 4;
  else return;
  let spec = "";
  while (y < A.length) {
    const v = A[y]!;
    if (v === "-s" || v === "--scope") {
      y += 2;
      continue;
    }
    if (!v.startsWith("-")) {
      spec = v;
      break;
    }
    y++;
  }
  if (!spec) return;
  const ok =
    A[2] === "marketplace"
      ? /kodflow\/claude-marketplace(\.git|\/)?$/.test(spec)
      : spec.endsWith("@kodflow");
  if (!ok)
    st.f.plugin = `claude plugin ${A[2]}${A[2] === "marketplace" ? ` ${A[3]}` : ""} ${spec}`;
}

/** The cheap gate of pre_bash: a line naming no verb we know leaves at once. */
export function gate(line: string): boolean {
  const t = /["'\\]/.test(line) ? line.replace(/["'\\]/g, "") : line;
  return (
    /git|gh|glab|curl|wget|http|skills|claude/.test(t) || line.includes("$'")
  );
}

/** What a Bash line does that a guard looks at. */
export async function inspect(
  line: string,
  ctx: GuardCtx,
): Promise<Findings | undefined> {
  if (!line || !gate(line)) return undefined;
  const p = parse(line);
  const rules = await ctx.patterns();
  const st: State = {
    f: { commit: false, force: false },
    gdir: "",
    hooks: false,
    amend: false,
    all: false,
    cgdir: "",
    scan: (kind, text) => scan(kind, text, rules),
  };
  for (let k = 0; k < p.commands.length; k++) {
    const cmd = p.commands[k]!;
    for (const r of cmd.redirs)
      if (modPath(r, ctx.home, ctx.configDir)) st.f.modWrite = r;
    const { argv: A, name } = argvOf(cmd);
    st.hooks = false;
    if (name === "claude") guardClaude(st, A);
    else if (name === "git") await guardGit(ctx, st, p, k, A);
    else if (name === "gh") await guardGh(ctx, st, p, k, A);
    else if (name === "glab") guardGlab(st, A);
    else if (["curl", "wget", "http", "https", "xh"].includes(name))
      guardHttp(st, name, A);
    else if (name === "cd") {
      const d = A[1] ?? "";
      st.gdir = d.startsWith("/") || !d || !st.gdir ? d : `${st.gdir}/${d}`;
    }
  }
  if (st.f.commit && !st.f.mcpJson) {
    const dir = st.cgdir || ctx.projectDir;
    const staged = changedPaths(
      (await ctx.git(dir, ["diff", "--cached", "--name-status", "-z"])) ?? "",
    ).find(isMcpJson);
    if (staged) st.f.mcpJson = `${staged} is staged`;
    else if (st.all) {
      const changed = changedPaths(
        (await ctx.git(dir, ["diff", "--name-status", "-z"])) ?? "",
      ).find(isMcpJson);
      if (changed)
        st.f.mcpJson = `${changed} is modified and git commit -a stages it`;
    }
  }
  return st.f;
}

/**
 * A forge tool that writes an mcp.json: a path a write tool names (a read
 * and a deletion are allowed), else, for a GitKraken add or commit naming no file, what the
 * repository would take in. pre_forge of on-tool.sh, doubled.
 */
export async function forgeMcpJson(
  tool: string,
  input: Record<string, any>,
  ctx: Pick<GuardCtx, "projectDir" | "git">,
): Promise<Refusal | undefined> {
  // A read or a deletion of one stays allowed
  if (
    !/^mcp__(github|gitlab)__.*(push_files|create_or_update_file|create_commit)$|^mcp__GitKraken__git_(add|commit)$/.test(
      tool,
    )
  )
    return undefined;
  const paths: unknown[] = [input.path, input.file_path];
  for (const f of Array.isArray(input.files) ? input.files : [])
    paths.push(typeof f === "string" ? f : (f?.path ?? f?.file_path));
  for (const a of Array.isArray(input.actions) ? input.actions : [])
    if (a?.action !== "delete") paths.push(a?.file_path);
  const named = paths.find((p) => typeof p === "string" && isMcpJson(p));
  if (named) return mcpJsonRefusal(`${tool}: ${named}`);
  const gk = /GitKraken__git_(add|commit)$/.test(tool);
  if (!gk || (Array.isArray(input.files) && input.files.length)) return undefined;
  let dir = typeof input.directory === "string" ? input.directory : ".";
  if (!dir.startsWith("/")) dir = `${ctx.projectDir}/${dir}`;
  if (tool.endsWith("git_add")) {
    // "XY path", the old path after a rename; Y is the working tree
    const w = (
      (await ctx.git(dir, ["status", "--porcelain", "-z", "--untracked-files=all"])) ?? ""
    ).split("\0");
    for (let i = 0; i < w.length; i++) {
      const e = w[i]!;
      if (e.length < 4) continue;
      if (e[0] === "R" || e[0] === "C") i++;
      if (e[1] === " " || e[1] === "D") continue;
      if (isMcpJson(e.slice(3)))
        return mcpJsonRefusal(`${tool}: ${e.slice(3)}, added with every file`);
    }
    return undefined;
  }
  const staged = changedPaths(
    (await ctx.git(dir, ["diff", "--cached", "--name-status", "-z"])) ?? "",
  ).find(isMcpJson);
  return staged ? mcpJsonRefusal(`${tool}: ${staged} is staged`) : undefined;
}

const ROOT_OK =
  /^([A-Za-z_][A-Za-z0-9_]*=[^ \t\n\r\f\v]*[ \t\n\r\f\v]+)*ROOT_OK=1([ \t\n\r\f\v]|$)/;

/** The command to run instead of a forced push (BLOCK 4). */
export function withLease(line: string): string {
  let fixed = line
    .replace(/(^|\s)(--force|-f)(?=\s|$)/g, "$1--force-with-lease")
    .replace(/(\s)\+(\S+)/g, "$1$2");
  if (!fixed.includes("--force-with-lease")) fixed += " --force-with-lease";
  return fixed;
}

/** The first block on-tool.sh's pre_bash would raise, in its order. */
export async function verdict(
  line: string,
  f: Findings,
  ctx: GuardCtx,
): Promise<Refusal | undefined> {
  if (f.root && ctx.rootMain && !ROOT_OK.test(line))
    return {
      motif: "root",
      title: "BLOCKED — code production in a repository is delegated",
      lines: [
        f.root,
        "Dispatch the epic's subagent (task_focus the epic first), or SendMessage it if it is running;",
        "it works in its own worktree and delivers through a PR.",
        "A genuine exception: prefix the Bash line with ROOT_OK=1 (KODFLOW_ROOT=off turns the gate off).",
      ],
    };
  if (f.noVerify)
    return {
      motif: "no-verify",
      title: `COMMAND BLOCKED — skipping git hooks is forbidden (${f.noVerify})`,
      lines: [
        "Local git hooks are the second layer of the attribution and secret guards.",
        "If a hook is wrong, fix the hook; do not skip it.",
      ],
    };
  if (f.attr)
    return {
      motif: f.attr.motif,
      title: `${f.attr.kind === "pr" ? "PULL REQUEST" : "COMMIT"} BLOCKED — AI reference detected`,
      lines: [
        `Forbidden pattern: ${f.attr.pattern}`,
        "Remove AI attribution (co-authored-by, generated by, the robot emoji) and, in a commit, workflow leaks (.claude/ paths, Plan: footers).",
      ],
    };
  if (f.mcpJson) return mcpJsonRefusal(f.mcpJson);
  if (f.modWrite)
    return {
      motif: "mod-write",
      title: `COMMAND BLOCKED — plugin machinery written under a skills directory (${f.modWrite})`,
      lines: ["Ship it as a plugin of the kodflow marketplace instead."],
    };
  if (f.plugin)
    return {
      motif: "plugin-source",
      title: `COMMAND BLOCKED — plugin from outside the kodflow marketplace (${f.plugin})`,
      lines: ["Ask the user to install it themselves if it is wanted."],
    };
  if (f.force)
    return {
      motif: "force",
      title: "COMMAND BLOCKED — forced push",
      lines: [
        "--force, -f and a +refspec overwrite the remote without checking what is there.",
        `Run instead: ${withLease(line)}`,
      ],
    };
  if (ctx.agentId) {
    if (f.merge)
      return {
        motif: "merge",
        title: `COMMAND BLOCKED — a subagent does not merge (${f.merge})`,
        lines: [
          "Merging is the main thread's decision, after the user's explicit OK.",
          "Report the PR and its CI state; stop there.",
        ],
      };
    if (f.defaultPush)
      return {
        motif: "push-default",
        title: `COMMAND BLOCKED — a subagent does not push to the default branch (${f.defaultPush})`,
        lines: ["Push your feature branch and open a PR."],
      };
  } else if (f.merge && !(await ctx.mergeAllowed()))
    return {
      motif: "merge",
      title: `COMMAND BLOCKED — merge without the user's OK (${f.merge})`,
      lines: [
        "A merge from the main thread needs green CI and the user's answer to the kodflow merge question.",
      ],
    };
  return undefined;
}

/** A refusal as the model reads it, laid out like the shell's _block. */
export function refusalText(r: Refusal): string {
  const bar = "═══════════════════════════════════════════════";
  return [
    bar,
    `  ❌ ${r.title}`,
    bar,
    ...r.lines.map((l) => `  ${l}`),
    `  [motif:${r.motif}]`,
  ].join("\n");
}

